	// observation is behind only if it lacks this tip: a tip fetched after
	// the query may already contain this PR's own merge.
	targetTips := make(map[string]prTargetFreshness)
	for _, task := range watched {
		var targetTip prTargetFreshness
		if cfg.Defaults.RequireCurrentTarget {
			branch := taskTargetBranch(project, task)
			fetched := false
			if targetTip, fetched = targetTips[branch]; !fetched {
				var fetchErr error
				if targetTip, fetchErr = fetchPRTargetTip(ctx, project.Root, branch); fetchErr != nil {
					failedTasks[task.ID] = fetchErr
					staleBeforeQuery[task.ID] = true
					continue
				}
				targetTips[branch] = targetTip
			}
		}
		headSHA := task.GatedSHA
		if headSHA == "" && task.WorktreePath != "" && task.Branch != "" {
			headSHA, _ = gitOutput(ctx, task.WorktreePath, "rev-parse", "refs/heads/"+task.Branch)
		}
		if headSHA == "" {
			previous, previousErr := db.LatestPRObservation(ctx, task.ID)
			if previousErr == nil && previous.PRURL == task.PRURL {
				headSHA = previous.HeadSHA
			}
		}
		if headSHA == "" {
			staleBeforeQuery[task.ID] = true
			continue
		}
		if !cfg.Defaults.RequireCurrentTarget {
			continue
		}
		freshness, freshnessErr := targetTip.of(ctx, project.Root, headSHA)
		if freshnessErr != nil {
			failedTasks[task.ID] = freshnessErr
			staleBeforeQuery[task.ID] = true
			continue
		}
		if !freshness.Fresh {
			// The target may have advanced because this PR just merged. Defer
			// queuing a sync instruction until GraphQL confirms the PR is open.
			staleBeforeQuery[task.ID] = true
		}
	}
	forge, forgeErr := forgeForRepository(ctx, project.Root, cfg, "")
	globalFailure := ""
	if forgeErr != nil {
		globalFailure = truncate(forgeErr.Error(), 300)
	}
	gitlabTargets := make([]store.Task, 0)
	for _, task := range watched {
		if forgeErr != nil {
			continue
		}
		_, refErr := forgeReference(task.PRURL, forge)
		if refErr != nil {
			failedTasks[task.ID] = refErr
			continue
		}
		if forge.Kind == "gitlab" {
			gitlabTargets = append(gitlabTargets, task)
		} else {
			targets = append(targets, prWatchTarget{Task: task, Pull: "pr" + strconv.Itoa(task.Seq), SkipChecks: staleBeforeQuery[task.ID]})
		}
	}
	query, targets := pullRequestGraphQLQuery(targets)
	pulls := make(map[int64]*ghPullRequest, len(targets))
	var response ghQueryResponse
	forgeAnswered := false
	if query != "" {
		output, stderr, commandErr := graphQLCommandOutput(ctx, project.Root, query)
		if err := json.Unmarshal([]byte(output), &response); err != nil {
			failure := "invalid GraphQL response: " + err.Error()
			if commandErr != nil {
				failure = truncate(strings.TrimSpace(stderr+" "+commandErr.Error()), 300)
			}
			if _, recordErr := db.RecordPRPoll(ctx, project.ID, now.UnixMilli(), failure); recordErr != nil {
				return recordErr
			}
			return nil
		}
		if commandErr != nil && (len(response.Errors) == 0 || errors.Is(commandErr, context.Canceled) || errors.Is(commandErr, context.DeadlineExceeded)) {
			globalFailure = truncate(strings.TrimSpace(stderr+" "+commandErr.Error()), 300)
		}
		hasRepositoryData := len(response.Data.Repositories) > 0
		forgeAnswered = hasRepositoryData
		if !hasRepositoryData {
			globalFailure = truncate(strings.TrimSpace(globalFailure+" GraphQL response omitted repository data"), 300)
		}
